+/// The checkout facts that a release using the [`ExecutionTrustProfile`][1]
+/// `GitCommit` profile is allowed to rely on.
+///
+/// This is deliberately an observation rather than a boolean such as
+/// `is_clean()`: the release graph must bind its validation to the canonical
+/// repository root and the complete commit identity it actually observed.
+/// The fields stay private so evidence can only be constructed by the VCS
+/// observation path, not by an arbitrary graph caller.
+///
+/// [1]: callisto_model::ExecutionTrustProfileV1
+#[derive(Debug, PartialEq, Eq)]
+pub struct GitCommitTrustEvidence {
+    canonical_root: PathBuf,
+    head: CommitSha,
+    head_disposition: GitHeadDisposition,
+    allowed_ignored_paths: Vec<PathBuf>,
+}
+
+impl GitCommitTrustEvidence {
+    pub(crate) fn new(
+        canonical_root: PathBuf,
+        head: CommitSha,
+        head_disposition: GitHeadDisposition,
+        allowed_ignored_paths: Vec<PathBuf>,
