+    /// The complete, normalized commit that `HEAD` resolved to.
+    pub fn head(&self) -> &CommitSha {
+        &self.head
+    }
+
+    /// Whether `HEAD` had no symbolic branch reference at observation time.
+    pub fn head_disposition(&self) -> GitHeadDisposition {
+        self.head_disposition
+    }
