+    /// Ignored paths that were present and accepted by the fixed release
+    /// policy. This list is informational: its existence does not weaken the
+    /// clean-worktree guarantee for tracked or untracked source files.
+    pub fn allowed_ignored_paths(&self) -> &[PathBuf] {
+        &self.allowed_ignored_paths
+    }
+}
+
+/// The symbolic-reference status of `HEAD` at the time trust evidence was
+/// observed. Detached checkouts are valid release inputs when their full
+/// [`CommitSha`] matches the intent's source identity.
+#[derive(Clone, Copy, Debug, PartialEq, Eq)]
+pub enum GitHeadDisposition {
+    Attached,
