    // normal relative component avoids turning a future parser quirk into an
    // allowlist escape.
    if path.is_absolute()
        || path
            .components()
            .any(|component| !matches!(component, std::path::Component::Normal(_)))
    {
        return false;
    }

    let rendered = path.to_string_lossy().replace('\\', "/");
    RELEASE_IGNORED_ALLOWLIST.iter().any(|allowed| {
        allowed.strip_suffix('/').map_or_else(
            || rendered == *allowed,
            |directory| rendered == directory || rendered.starts_with(&format!("{directory}/")),
